import logging
from taf.ue.plugin.mtk.exceptions import (ContextIdHasBeenReserved, ContextAliasNotInStore,
                                          NoFreeContextId)


class ContextAliasStore(object):

    _instance = None
    _MAX_CONTEXT_NUMBER = 1000
    _alias_store = {}

    def __new__(cls, *args, **kwargs):
        if not cls._instance:
            cls._instance = super(ContextAliasStore, cls).__new__(cls, *args, **kwargs)
        return cls._instance

    def create_context_id(self, alias):
        if alias in self._alias_store:
            raise ContextIdHasBeenReserved("alias {} is already in store".format(alias))

        context_id = self._create_free_context_id()
        self._store_context_id(context_id, alias)
        logging.info("alias store create alias {} context id {} successfully".format(alias, context_id))
        return context_id

    def get_context_id(self, alias):
        if alias not in self._alias_store:
            raise ContextAliasNotInStore("alias {} is not existed in store".format(alias))
        return self._alias_store[alias]

    def release_context_id(self, alias):
        if alias in self._alias_store:
            logging.info("alias store release alias {} context id successfully".format(alias))
            return self._alias_store.pop(alias)
        logging.error("alias={} is not existed in alias store".format(alias))

    def release_all_context_ids(self):
        logging.info("release all context ids {} successfully".format(self._alias_store))
        self._alias_store.clear()

    def _create_free_context_id(self):
        for context_id in range(1, self._MAX_CONTEXT_NUMBER):
            if context_id not in self._alias_store.values():
                return context_id
        raise NoFreeContextId("no free context id")

    def _store_context_id(self, context_id, alias):
        self._alias_store[alias] = context_id
